// Illustrations des exercices de calcul (SVG intégrés, une par exercice du jeu de départ)
export const CALC_IMG = {
  "c1": "data:image/svg+xml;base64,",
  "c2": "data:image/svg+xml;base64,",
  "c3": "data:image/svg+xml;base64,",
  "c4": "data:image/svg+xml;base64,",
  "c5": "data:image/svg+xml;base64,",
  "c6": "data:image/svg+xml;base64,"
};
export const calcImg = (ex) => (ex && (ex.image || CALC_IMG[ex.id])) || "";
